package com.gathin.tvhome;
import android.app.*;import android.os.*;import android.widget.*;import java.util.*;
/** Full paired-device actions. Input/unknown accessories require explicit alternate-control confirmation. */
final class SessionDevicesUi {
 static void show(Activity a){if(!SessionSettingsUi.ready(a))return;SessionSettingsUi.read(a,SettingsSessionClient.BONDED,new Bundle(),result->{ArrayList<Bundle> devices=result.getParcelableArrayList("devices");if(devices==null||devices.isEmpty()){Toast.makeText(a,"No paired devices.",Toast.LENGTH_LONG).show();return;}String[] labels=new String[devices.size()];for(int i=0;i<labels.length;i++)labels[i]=devices.get(i).getString("name")+(devices.get(i).getBoolean("connected")?" (connected)":"");final ArrayList<Bundle> entries=devices;AlertDialog d=new SettingsPopup.Builder(a).setTitle("Paired devices").setItems(labels,(dialog,which)->details(a,entries.get(which))).setNegativeButton("Close",null).create();d.show();SettingsPopup.style(d);});}
 private static void details(Activity a,Bundle device){boolean connected=device.getBoolean("connected");AlertDialog d=new SettingsPopup.Builder(a).setTitle(device.getString("name")).setItems(new String[]{"Rename",connected?"Disconnect":"Connect","Forget pairing"},(dialog,which)->{
  if(which==0){rename(a,device);return;}String action=which==2?"forget":connected?"disconnect":"connect";boolean alternate=!device.getBoolean("audio")&&!"connect".equals(action);
  LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(28,16,28,16);TextView note=new TextView(a);note.setTextColor(0xfff5f5fa);note.setTextSize(18);note.setText("forget".equals(action)?"This removes the pairing. You will need to pair this device again.":"disconnect".equals(action)?"This can disconnect your remote or audio.":"Connect this paired accessory.");box.addView(note);
  CheckBox backup=new CheckBox(a);backup.setText("I have a working IR remote or USB input device");backup.setTextColor(0xfff5f5fa);if(alternate)box.addView(backup);
  AlertDialog confirm=new SettingsPopup.Builder(a).setTitle("forget".equals(action)?"Forget pairing?":"disconnect".equals(action)?"Disconnect device?":"Connect device?").setView(box).setPositiveButton("Confirm",null).setNegativeButton("Cancel",null).create();confirm.show();SettingsPopup.style(confirm);confirm.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocus();
  confirm.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(alternate&&!backup.isChecked()){Toast.makeText(a,"Confirm alternative control first.",Toast.LENGTH_LONG).show();return;}Bundle input=new Bundle();input.putString("address",device.getString("address"));input.putString("action",action);input.putBoolean("backup_control",backup.isChecked());confirm.dismiss();SessionSettingsUi.change(a,SettingsSessionClient.DEVICE,input,()->show(a));});
 }).setNegativeButton("Back",(dialog,which)->show(a)).create();d.show();SettingsPopup.style(d);}
 private static void rename(Activity a,Bundle device){EditText name=new EditText(a);name.setSingleLine(true);name.setTextColor(0xfff5f5fa);name.setText(device.getString("name"));name.setPadding(32,20,32,20);AlertDialog dialog=new SettingsPopup.Builder(a).setTitle("Rename device").setView(name).setPositiveButton("Save",null).setNeutralButton("Use original device name",null).setNegativeButton("Cancel",null).create();dialog.show();SettingsPopup.style(dialog);java.util.function.Consumer<String> apply=value->{try{SettingsSessionPolicy.alias(value);Bundle input=new Bundle();input.putString("address",device.getString("address"));input.putString("action","rename");input.putString("original_alias",device.getString("alias"));input.putString("alias",value);dialog.dismiss();SessionSettingsUi.change(a,SettingsSessionClient.DEVICE,input,()->show(a));}catch(IllegalArgumentException invalid){name.setError(invalid.getMessage());}};dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->apply.accept(name.getText().toString()));dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->apply.accept(null));}
 private SessionDevicesUi(){}
}
